101:export function createJoint(ctx: Ctx, name: string, options: JointOptions) {
102:  if (!JOINT_NAME.test(name)) throw new Error(`Joint name "${name}" must match ${JOINT_NAME}`);
103:  if (ctx.joints.has(name)) throw new Error(`Joint "${name}" already exists`);
104:  const at = toPoint(options.at, "joint()");
105:  const parent =
106:    options.parent === undefined && !ctx.rootJoint
107:      ? null
108:      : boneFor(ctx, options.parent, [options.at], at, "joint(): parent");
109:  const direction = options.aim
110:    ? toPoint(options.aim, "joint()").sub(at)
111:    : options.dir
112:      ? toDirection(options.dir, "joint()")
113:      : null;
114:  const quat = direction ? aim(direction, options.up) : (parent?.quat ?? new Quaternion());
115:  const object = new Group();
116:  object.name = name;
117:  object.userData.joint = name;
118:  if (options.group) object.userData.group = options.group;
119:  setWorld(object, parent ? parent.object : ctx.root, at, quat);
120:  const joint = new Joint(name, object, parent, ctx);
121:  ctx.joints.set(name, joint);
122:  if (!parent) {
123:    ctx.rootJoint = joint;
124:    // Meshes added straight to `b.root` (outside every joint) ride the root joint.
125:    ctx.root.userData.bone = name;
126:  }
127:  const { role } = options;
128:  if (role)
129:    ctx.rig.push(() => ({
130:      joint: {
131:        name,
132:        role,
133:        side: sideOf([joint]),
134:        ...(role === "jaw" || role === "hinge" ? { hinge: tuple(joint.dir([1, 0, 0])) } : {}),
135:      },
136:    }));
137:  return joint;
138:}
