152:/**
153: * Rotate a joint, with everything under it: a new rest pose (open a jaw, raise a tail, fold a ring's joint group)
154: * without rebuilding. Joints read the scene, frames are stored on their bones, chains, sweeps and surfaces map
155: * their build-time data through each joint's motion, and blend-skinned meshes re-deform, so every handle stays valid.
156: */
157:export function pose(ctx: Ctx, ref: JointRef, rotation: PoseRotation) {
158:  const joint = resolveJoint(ctx, ref, "pose(): joint");
159:  let pivot = joint.at;
160:  let delta: Quaternion;
161:  if ("isQuaternion" in rotation) delta = rotation.clone();
162:  else if ("about" in rotation) {
163:    const hinge = toFrame(rotation.about, "pose(): about");
164:    pivot = hinge.at;
