10:const isMeshList = (target: Glowing): target is readonly Mesh[] => Array.isArray(target);
11:
12:/** One glowing copy per source material and strength, so parts that shared a material still share one. */
13:const copies = new WeakMap<MeshStandardMaterial, Map<number, MeshStandardMaterial>>();
14:
15:/**
16: * Makes `target` emit its own colours at `strength` (1 = its colour at full brightness regardless of light; more
17: * blooms brighter where the renderer allows). Flat colours and textures (drawings, cards, pixel tiles) glow;
18: * painted surfaces don't, so give a glowing part a flat colour or a texture. Returns `target`.
19: */
20:export function glow<T extends Glowing>(target: T, strength = 1): T {
21: const source: Glowing = target;
22: const meshes: readonly Mesh[] = isMeshList(source)
23:  ? source
24:  : "isMesh" in source
25:   ? [source]
26:   : "meshes" in source
27:    ? source.meshes
28:    : [source.mesh];
29: for (const mesh of meshes) {
30:  const material = mesh.material;
31:  if (!(material instanceof MeshStandardMaterial))
32:   throw new Error(`glow(): ${mesh.name || "a mesh"} has no single MeshStandardMaterial`);
33:  if (material.name === "paint")
34:   throw new Error(`glow(): ${mesh.name || "a part"} is painted; give a glowing part a flat colour or a texture`);
35:  let byStrength = copies.get(material);
36:  if (!byStrength) copies.set(material, (byStrength = new Map()));
37:  let copy = byStrength.get(strength);
38:  if (!copy) {
39:   copy = material.clone();
40:   copy.emissive.copy(material.color);
41:   copy.emissiveMap = material.map;
42:   copy.emissiveIntensity = strength;
43:   byStrength.set(strength, copy);
44:  }
45:  mesh.material = copy;
46: }
